def main():
    n = int(input())
    q = list(map(int, input().split()))
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))

    am = 10**6
    for i in range(n):
        if a[i] == 0:
            continue
        if am > q[i] // a[i]:
            am = q[i] // a[i]

    bm = 10**6
    for i in range(n):
        if b[i] == 0:
            continue
        if bm > q[i] // b[i]:
            bm = q[i] // b[i]

    ans = 0

    for i in range(am + 1):
        k = []
        for j in range(n):
            k.append(q[j] - i * a[j])

        t = 0
        while True:
            can_make_b = True
            for j in range(n):
                if k[j] < b[j]:
                    can_make_b = False
                    break

            if not can_make_b:
                break

            t += 1
            for j in range(n):
                k[j] -= b[j]

        ans = max(ans, i + t)

    print(ans)
